package com.battlemanson.codekanban;

import android.app.*;
import android.os.Bundle;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class MainActivity extends Activity {
    private static final int INK=Color.rgb(30,41,59), MUTED=Color.rgb(100,116,139), ACCENT=Color.rgb(67,56,202), BG=Color.rgb(245,247,252);
    private JSONObject data; private String current="", tab="boards"; private LinearLayout root, content;
    private final String[] palette={"#6366f1","#0d9488","#f59e0b","#e11d48","#0284c7","#9333ea"};
    private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private JSONObject obj(){return new JSONObject();} private JSONArray arr(){return new JSONArray();}
    private JSONObject put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(JSONException e){throw new IllegalStateException(e);}return o;}
    private String id(){return UUID.randomUUID().toString();}
    private JSONArray array(JSONObject o,String k){JSONArray a=o.optJSONArray(k);if(a==null){a=arr();put(o,k,a);}return a;}
    private JSONObject at(JSONArray a,int i){return a.optJSONObject(i);}
    private JSONObject find(JSONArray a,String id){for(int i=0;i<a.length();i++){JSONObject o=at(a,i);if(o!=null&&id.equals(o.optString("id")))return o;}return null;}
    private JSONObject board(){return find(array(data,"boards"),current);}
    private JSONObject col(JSONObject b,String id){return find(array(b,"columns"),id);}
    private void remove(JSONArray a,String id){for(int i=0;i<a.length();i++)if(id.equals(at(a,i).optString("id"))){a.remove(i);return;}}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(38,32,102));getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);load();show();}
    private void load(){
        android.util.AtomicFile file=new android.util.AtomicFile(new File(getFilesDir(),"boards.json"));
        try(FileInputStream in=file.openRead()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);data=new JSONObject(out.toString("UTF-8"));}
        catch(FileNotFoundException e){data=obj();array(data,"boards");put(data,"defaults",new JSONArray(Arrays.asList("Backlog","To Do","Doing","Done")));}
        catch(Exception e){new AlertDialog.Builder(this).setTitle("Unable to open boards").setMessage("Your saved data could not be read. It has not been replaced. Close the app and recover it before continuing.\n\n"+e.getMessage()).setPositiveButton("Close",(d,w)->finish()).setCancelable(false).show();data=null;}
    }
    private boolean save(){android.util.AtomicFile file=new android.util.AtomicFile(new File(getFilesDir(),"boards.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(data.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);return true;}catch(Exception e){if(out!=null)file.failWrite(out);Toast.makeText(this,"Could not save: "+e.getMessage(),Toast.LENGTH_LONG).show();return false;}}
    private GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    private void pad(View v,int n){v.setPadding(dp(n),dp(n),dp(n),dp(n));}
    private TextView action(String title,Runnable r){TextView t=text(title,15,ACCENT,true);pad(t,12);t.setGravity(Gravity.CENTER);t.setOnClickListener(v->r.run());return t;}
    private void show(){if(data==null)return;root=vertical();root.setBackgroundColor(BG);setContentView(root);
        LinearLayout header=vertical();header.setBackgroundColor(Color.WHITE);header.setPadding(dp(20),dp(18),dp(20),dp(12));root.addView(header);
        TextView brand=text("CODE KANBAN",12,ACCENT,true);header.addView(brand);
        String title=tab.equals("boards")?(board()==null?"Your boards":board().optString("name")):tab.equals("all")?"Across boards":"Default board";
        TextView h=text(title,27,INK,true);header.addView(h);TextView sub=text(tab.equals("boards")?(board()==null?"Organize work, your way":"Board · "+path(board())):tab.equals("all")?"Work items from every board":"New boards start with these columns",13,MUTED,false);header.addView(sub);
        HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout nav=new LinearLayout(this);scroll.addView(nav);header.addView(scroll);
        nav.addView(action("Boards",()->{tab="boards";show();}));nav.addView(action("All work",()->{tab="all";show();}));nav.addView(action("Defaults",()->{tab="defaults";show();}));
        ScrollView sv=new ScrollView(this);sv.setFillViewport(true);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));content=vertical();content.setPadding(dp(16),dp(16),dp(16),dp(28));sv.addView(content);
        if(tab.equals("defaults"))defaults();else if(tab.equals("all"))all();else if(board()==null)boards();else boardView();
    }
    private String path(JSONObject b){ArrayList<String> parts=new ArrayList<>();HashSet<String> seen=new HashSet<>();while(b!=null&&seen.add(b.optString("id"))){parts.add(b.optString("name"));b=find(array(data,"boards"),b.optString("parent"));}Collections.reverse(parts);return android.text.TextUtils.join(" / ",parts);}
    private void section(String s){TextView t=text(s,18,INK,true);t.setPadding(dp(4),dp(18),dp(4),dp(10));content.addView(t);}
    private LinearLayout tile(){LinearLayout l=vertical();pad(l,16);l.setBackground(shape(Color.WHITE,Color.rgb(225,230,240)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);content.addView(l,p);return l;}
    private void button(String s,Runnable r){TextView b=action(s,r);b.setTextColor(Color.WHITE);b.setBackground(shape(ACCENT,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);content.addView(b,p);}
    private void empty(String s){TextView t=text(s,15,MUTED,false);pad(t,16);content.addView(t);}
    private void boards(){button("+ Create board",()->newBoard(""));JSONArray boards=array(data,"boards");int count=0;for(int i=0;i<boards.length();i++){JSONObject b=at(boards,i);if(!b.optString("parent").isEmpty())continue;boardTile(b);count++;}if(count==0)empty("Create your first board to start organizing work.");}
    private void boardTile(JSONObject b){LinearLayout l=tile();l.addView(text("▦  "+b.optString("name"),18,INK,true));l.addView(text(countCards(b)+" work items  ·  "+childCount(b.optString("id"))+" nested boards",13,MUTED,false));l.setOnClickListener(v->{current=b.optString("id");show();});}
    private int countCards(JSONObject b){int n=0;JSONArray a=array(b,"columns");for(int i=0;i<a.length();i++)n+=array(at(a,i),"cards").length();return n;}
    private int childCount(String parent){int n=0;JSONArray a=array(data,"boards");for(int i=0;i<a.length();i++)if(parent.equals(at(a,i).optString("parent")))n++;return n;}
    private void newBoard(String parent){input("Create board","Board name","",name->{JSONObject b=put(put(put(obj(),"id",id()),"name",name),"parent",parent);JSONArray columns=arr(),defs=array(data,"defaults");for(int i=0;i<defs.length();i++)columns.put(newColumn(defs.optString(i),palette[i%palette.length]));put(b,"columns",columns);array(data,"boards").put(b);if(save()){current=b.optString("id");show();}});}
    private JSONObject newColumn(String name,String color){return put(put(put(put(obj(),"id",id()),"name",name),"color",color),"cards",arr());}
    private void boardView(){JSONObject b=board();if(b==null){current="";show();return;}String bid=current;
        LinearLayout row=new LinearLayout(this);row.addView(action("‹ Back",()->{current=b.optString("parent");show();}));row.addView(action("+ Nested board",()->newBoard(bid)));row.addView(action("⋮",()->boardMenu(b)));content.addView(row);
        JSONArray boards=array(data,"boards");boolean children=false;for(int i=0;i<boards.length();i++){JSONObject child=at(boards,i);if(bid.equals(child.optString("parent"))){if(!children)section("Nested boards");children=true;boardTile(child);}}
        section("Columns");JSONArray cols=array(b,"columns");for(int i=0;i<cols.length();i++)columnView(b,at(cols,i));button("+ Add column",()->input("Add column","Column name","",name->{cols.put(newColumn(name,palette[cols.length()%palette.length]));save();show();}));
    }
    private void boardMenu(JSONObject b){new AlertDialog.Builder(this).setTitle(b.optString("name")).setItems(new String[]{"Rename board","Delete board"},(d,w)->{if(w==0)input("Rename board","Board name",b.optString("name"),n->{put(b,"name",n);save();show();});else new AlertDialog.Builder(this).setTitle("Delete board?").setMessage("This deletes the board, all nested boards, and their work items.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,y)->{String parent=b.optString("parent");deleteTree(b.optString("id"));current=parent;save();show();}).show();}).show();}
    private void deleteTree(String id){JSONArray bs=array(data,"boards");ArrayList<String> children=new ArrayList<>();for(int i=0;i<bs.length();i++)if(id.equals(at(bs,i).optString("parent")))children.add(at(bs,i).optString("id"));for(String child:children)deleteTree(child);remove(bs,id);}
    private void columnView(JSONObject b,JSONObject c){LinearLayout box=tile();LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);box.addView(head);TextView title=text("●  "+c.optString("name")+"  "+array(c,"cards").length(),17,parseColor(c.optString("color")),true);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));head.addView(action("⋮",()->columnMenu(b,c)));
        JSONArray cards=array(c,"cards");for(int i=0;i<cards.length();i++){JSONObject card=at(cards,i);TextView t=text(card.optString("title")+summary(card),16,INK,false);t.setPadding(dp(12),dp(14),dp(12),dp(14));t.setBackground(shape(BG,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(7);box.addView(t,p);t.setOnClickListener(v->editCard(b,c,card));}box.addView(action("+ Add work item",()->input("New work item","Title","",name->{JSONObject card=put(put(put(obj(),"id",id()),"title",name),"tasks",arr());put(card,"comments",arr());cards.put(card);save();show();})));}
    private int parseColor(String s){try{return Color.parseColor(s);}catch(Exception e){return ACCENT;}}
    private String summary(JSONObject c){JSONArray tasks=array(c,"tasks");int done=0;for(int i=0;i<tasks.length();i++)if(at(tasks,i).optBoolean("done"))done++;String due=c.optString("due");return (tasks.length()>0?"\n✓ "+done+"/"+tasks.length():"")+(due.isEmpty()?"":"   ◷ "+due);}
    private void columnMenu(JSONObject b,JSONObject c){new AlertDialog.Builder(this).setTitle(c.optString("name")).setItems(new String[]{"Rename","Change color","Delete column"},(d,w)->{if(w==0)input("Rename column","Name",c.optString("name"),s->{put(c,"name",s);save();show();});else if(w==1)new AlertDialog.Builder(this).setTitle("Column color").setItems(new String[]{"Indigo","Teal","Amber","Rose","Blue","Purple"},(x,n)->{put(c,"color",palette[n]);save();show();}).show();else if(array(b,"columns").length()==1)Toast.makeText(this,"Keep at least one column",Toast.LENGTH_SHORT).show();else new AlertDialog.Builder(this).setTitle("Delete column?").setMessage("Its work items will also be deleted.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,n)->{remove(array(b,"columns"),c.optString("id"));save();show();}).show();}).show();}
    private void all(){EditText search=new EditText(this);search.setSingleLine();search.setHint("Search work items");content.addView(search);LinearLayout results=vertical();content.addView(results);Runnable render=()->{results.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);int count=0;JSONArray bs=array(data,"boards");for(int i=0;i<bs.length();i++){JSONObject b=at(bs,i);JSONArray cs=array(b,"columns");for(int j=0;j<cs.length();j++){JSONObject c=at(cs,j);JSONArray cards=array(c,"cards");for(int k=0;k<cards.length();k++){JSONObject card=at(cards,k);if(!card.toString().toLowerCase(Locale.ROOT).contains(q))continue;count++;TextView t=text(card.optString("title")+"\n"+path(b)+"  ·  "+c.optString("name")+summary(card),16,INK,false);pad(t,16);t.setBackground(shape(Color.WHITE,Color.LTGRAY));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);results.addView(t,p);t.setOnClickListener(v->editCard(b,c,card));}}}if(count==0){TextView t=text("No matching work items",15,MUTED,false);pad(t,16);results.addView(t);}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
    private void defaults(){empty("One column per line. Changes apply to new boards only.");EditText e=new EditText(this);e.setGravity(Gravity.TOP);e.setMinLines(5);JSONArray defs=array(data,"defaults");ArrayList<String> lines=new ArrayList<>();for(int i=0;i<defs.length();i++)lines.add(defs.optString(i));e.setText(android.text.TextUtils.join("\n",lines));e.setBackground(shape(Color.WHITE,Color.LTGRAY));pad(e,14);content.addView(e);section("Board template");button("Save default columns",()->{JSONArray a=arr();for(String line:e.getText().toString().split("\\n"))if(!line.trim().isEmpty())a.put(line.trim());if(a.length()==0){Toast.makeText(this,"Add at least one column",Toast.LENGTH_SHORT).show();return;}put(data,"defaults",a);if(save())Toast.makeText(this,"Defaults saved",Toast.LENGTH_SHORT).show();});}
    interface TextResult{void done(String s);}
    private void input(String title,String hint,String value,TextResult result){EditText e=new EditText(this);e.setSingleLine();e.setHint(hint);e.setText(value);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(e).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String s=e.getText().toString().trim();if(s.isEmpty()){e.setError("Required");return;}dialog.dismiss();result.done(s);}));dialog.show();}
    private EditText field(LinearLayout l,String label,String value,boolean multi){TextView t=text(label,13,MUTED,true);t.setPadding(0,dp(12),0,0);l.addView(t);EditText e=new EditText(this);e.setText(value);if(multi){e.setMinLines(2);e.setGravity(Gravity.TOP);e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);}else e.setSingleLine();l.addView(e);return e;}
    private void editCard(JSONObject b,JSONObject c,JSONObject card){ScrollView sc=new ScrollView(this);LinearLayout form=vertical();pad(form,20);sc.addView(form);EditText title=field(form,"Title",card.optString("title"),false),desc=field(form,"Description",card.optString("description"),true),labels=field(form,"Labels (comma separated)",card.optString("labels"),false),due=field(form,"Due date (e.g. 2026-12-31)",card.optString("due"),false),points=field(form,"Story points",card.optString("points"),false),priority=field(form,"Priority",card.optString("priority"),false),difficulty=field(form,"Difficulty",card.optString("difficulty"),false),ado=field(form,"ADO work item",card.optString("ado"),false),sm=field(form,"SM item",card.optString("sm"),false);
        TextView taskHead=text("CHECKLIST",13,MUTED,true);taskHead.setPadding(0,dp(20),0,dp(8));form.addView(taskHead);JSONArray tasks;try{tasks=new JSONArray(array(card,"tasks").toString());}catch(JSONException ex){throw new IllegalStateException(ex);}LinearLayout taskBox=vertical();form.addView(taskBox);Runnable taskRender=()->{taskBox.removeAllViews();for(int i=0;i<tasks.length();i++){JSONObject task=at(tasks,i);LinearLayout row=new LinearLayout(this);CheckBox check=new CheckBox(this);check.setText(task.optString("title"));check.setChecked(task.optBoolean("done"));row.addView(check,new LinearLayout.LayoutParams(0,-2,1));check.setOnCheckedChangeListener((v,on)->put(task,"done",on));row.addView(action("×",()->{remove(tasks,task.optString("id"));editCardRefresh(taskBox,tasks);}));taskBox.addView(row);}};taskRender.run();form.addView(action("+ Add task",()->input("Add task","Task","",s->{tasks.put(put(put(put(obj(),"id",id()),"title",s),"done",false));editCardRefresh(taskBox,tasks);})) );
        EditText comments=field(form,"Comments (one per line)",card.optString("commentsText"),true);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Work item").setView(sc).setNegativeButton("Cancel",(d,w)->show()).setNeutralButton("More",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->{dialog.getButton(-1).setOnClickListener(v->{String s=title.getText().toString().trim();if(s.isEmpty()){title.setError("Required");return;}put(card,"tasks",tasks);put(card,"title",s);put(card,"description",desc.getText().toString());put(card,"labels",labels.getText().toString());put(card,"due",due.getText().toString());put(card,"points",points.getText().toString());put(card,"priority",priority.getText().toString());put(card,"difficulty",difficulty.getText().toString());put(card,"ado",ado.getText().toString());put(card,"sm",sm.getText().toString());put(card,"commentsText",comments.getText().toString());save();dialog.dismiss();show();});dialog.getButton(-3).setOnClickListener(v->{dialog.dismiss();new AlertDialog.Builder(this).setItems(new String[]{"Move to column","Delete work item"},(d,w)->{if(w==0)moveCard(b,c,card);else new AlertDialog.Builder(this).setTitle("Delete work item?").setNegativeButton("Cancel",(a,z)->show()).setPositiveButton("Delete",(a,z)->{remove(array(c,"cards"),card.optString("id"));save();show();}).show();}).setOnCancelListener(d->show()).show();});});dialog.show();}
    private void editCardRefresh(LinearLayout box,JSONArray tasks){box.removeAllViews();for(int i=0;i<tasks.length();i++){JSONObject t=at(tasks,i);LinearLayout row=new LinearLayout(this);CheckBox cb=new CheckBox(this);cb.setText(t.optString("title"));cb.setChecked(t.optBoolean("done"));cb.setOnCheckedChangeListener((v,on)->put(t,"done",on));row.addView(cb,new LinearLayout.LayoutParams(0,-2,1));row.addView(action("×",()->{remove(tasks,t.optString("id"));editCardRefresh(box,tasks);}));box.addView(row);}}
    private void moveCard(JSONObject b,JSONObject from,JSONObject card){JSONArray cols=array(b,"columns");String[] names=new String[cols.length()];for(int i=0;i<names.length;i++)names[i]=at(cols,i).optString("name");new AlertDialog.Builder(this).setTitle("Move to column").setItems(names,(d,n)->{JSONObject to=at(cols,n);if(to!=from){remove(array(from,"cards"),card.optString("id"));array(to,"cards").put(card);save();}show();}).setOnCancelListener(d->show()).show();}
    @Override public void onBackPressed(){if(!tab.equals("boards")){tab="boards";show();}else if(board()!=null){current=board().optString("parent");show();}else super.onBackPressed();}
}
